#!/usr/bin/perl
use strict; use warnings;
my $BIN = '/workspace/dataset/test20_executable';

sub model_trunc {
    my ($s) = @_;
    return $s if length($s) <= 5;
    return substr($s,0,2) . '...';
}
sub model_l18 {
    # returns (aborted, text)
    my ($w) = @_;
    my $m = length($w);
    my $start;
    my $j = -1;
    for (my $i=$m-1; $i>=0; $i--) { if (substr($w,$i,1) eq ':') { $j=$i; last; } }
    if ($j >= 0) { $start = $j + 2; } else { $start = 1; }
    if ($start > $m) { return (1, ''); }
    return (0, substr($w,$start));
}

my $mismatch = 0; my $n = 0;
sub probe {
    my ($w, $label) = @_;
    $label = defined($label) ? $label : '';
    $n++;
    # write word to a file to pass safely
    open(my $fh, '>', '/tmp/w.bin') or die; binmode $fh; print $fh $w; close $fh;
