/// Faithful port. Must return Vec<u8>: the result can be invalid UTF-8.
pub fn truncate(s: &[u8], len: usize) -> Vec<u8> {
    const OMISSION: &[u8] = b"...";
    if s.len() <= len {
        return s.to_vec();
    }
    // Only len == 5 is ever exercised by the binary, so keep == 2.
    // NOTE: this subtraction is the *inferred* decomposition; it would underflow for
    // len < 3, and that regime is unobservable through this harness.
    let keep = len - OMISSION.len();
    let mut out = Vec::with_capacity(len);
    out.extend_from_slice(&s[..keep]);
    out.extend_from_slice(OMISSION);
    out
}

/// Exactly what line 17 does.
pub fn line17(word: &[u8]) -> Vec<u8> {
    truncate(word, 5)
