    let m = word.len();
    let start_in_word = match word.iter().rposition(|&b| b == b':') {
        Some(j) => j + 2, // pos = 6+j, start = 8+j, minus the 6-byte prefix
        None => 1,        // pos = 5,   start = 7,   minus the 6-byte prefix
    };
    if start_in_word > m {
        return Err(OutOfRange { pos: start_in_word + 6, size: m + 6 });
    }
    Ok(word[start_in_word..].to_vec())
}

/// IMPORTANT for whole-program fidelity: the binary computes ALL 20 result strings BEFORE
/// writing any of them, so a failure here must emit NOTHING on stdout -- not even lines 1-17.
/// (Proven with an unbuffered stdout, with a pty, and with a ~1 MB pending output.)
pub fn run_all(word: &[u8]) -> Result<Vec<String>, OutOfRange> {
    let mut lines: Vec<String> = Vec::with_capacity(20);
    // ... lines 1..16 ...
    lines.push(String::from_utf8_lossy(&super::truncate(word, 5)).into_owned()); // line 17
    lines.push(String::from_utf8_lossy(&line18(word)?).into_owned());            // line 18 (may fail)
    // ... lines 19, 20 ...
    Ok(lines) // caller prints only on Ok
}
